// tb.v: random-stimulus testbench for module_, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg clk = 1'b0;
    reg [4:0] bit_ = 5'd0;
    wire [3:0] logic_;
    wire event_;
    wire _9lives;
    reg [4:0] stim [0:239];
    integer i;

    module_ dut (
        .clk(clk),
        .bit_(bit_),
        .logic_(logic_),
        .event_(event_),
        ._9lives(_9lives)
    );

    task cycle_clk;
        begin
            clk = 1'b1;
            #5;
            clk = 1'b0;
            #5;
        end
    endtask

    task do_reset;
        begin
            #1;
            cycle_clk;
            cycle_clk;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {bit_} = stim[i];
            #1;
            $display("D %0d %h %h %h", i, logic_, event_, _9lives);
            cycle_clk;
        end
        $finish;
    end
endmodule
